  const r=editDomain==='navigation'?region():undefined,layer=r&&level().layers.find(l=>l.id===r.layerId),vertex=r&&selections.length===1&&!layer?.locked?controlPoints(r).findIndex(v=>Math.hypot(v.x-p.x,v.y-p.y)<10/view.zoom):-1;
