function cloneLibraryAsset(id=chosenAsset,inspect=true):EditorAsset {
  if(playing)throw new Error('Dừng Test để nhân bản asset.');
  if(project.assets.length>=200)throw new Error('Thư viện tối đa 200 asset.');
  if(!project.assets.some(a=>a.id===id))throw new Error('Chọn asset trong thư viện để nhân bản.');
  let copy:EditorAsset|undefined;
  const applied=edit(()=>{copy=duplicateAsset(project,id);const thumbnail=thumbnails.get(id);if(thumbnail)thumbnails.set(copy.id,thumbnail);if(inspect){clearSelection();chosenAsset=copy.id;chosenPrefab='';inspectorContext='asset';}});
  if(!applied||!copy)throw new Error('Không nhân bản được asset. Kiểm giới hạn thư viện / dữ liệu.');
  if(inspect){setTool('select');ui();}status(`Đã tạo “${copy.name}”. Bản sao độc lập trong Assets; Ctrl+S lưu, Ctrl+Z hoàn tác.`);
  return copy;
}
