  if((e.ctrlKey||e.metaKey)&&key==='a'){e.preventDefault();selectAll();return;}if((e.ctrlKey||e.metaKey)&&key==='g'){e.preventDefault();groupSelection(e.shiftKey);return;}if((e.ctrlKey||e.metaKey)&&key==='c'){e.preventDefault();copySelection();return;}if((e.ctrlKey||e.metaKey)&&key==='v'){e.preventDefault();pasteSelection();return;}
