  if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();history(!e.shiftKey);}else if((e.ctrlKey||e.metaKey)&&key==='d'){e.preventDefault();duplicate();}else if(key==='delete'||key==='backspace'){e.preventDefault();remove();}else if(key==='enter'&&draft.length)finish();else if(key==='v')setTool('select');else if(key==='h')setTool('pan');else if(key===' '){e.preventDefault();space=true;}
