  for(const o of l.objects){const a=project.assets.find(a=>a.id===o.assetId);if(!a)continue;const box=bounds(o,a);if((box.left+box.w)*view.zoom+view.x<0||box.left*view.zoom+view.x>viewport.clientWidth||(box.top+box.h)*view.zoom+view.y<0||box.top*view.zoom+view.y>viewport.clientHeight)continue;for(const part of a.parts){const layer=l.layers.find(x=>x.id===(part.cover?o.coverLayerId:o.layerId));const base=l.layers.find(x=>x.id===o.layerId);if(!layer||(!playing&&(!layer.visible||(el<HTMLInputElement>('solo-layer').checked&&layer.id!==activeLayer)))||(playing&&(!layer.enabled||!base?.enabled)))continue;rows.push({o,a,part,band:layer.kind==='ground'?0:layer.kind==='decor'?1:2,order:l.layers.indexOf(layer),cover:part.cover||layer.kind==='cover'});}}
  rows.sort((a,b)=>a.band-b.band||(a.band===2?a.o.y-b.o.y||Number(a.cover)-Number(b.cover):a.order-b.order)||objectOrder.get(a.o.id)!-objectOrder.get(b.o.id)!);
  const frame=playing?atlas.frames[animation.frameId]:null;
  if(frame&&!actorFrameMasks.has(animation.frameId))actorFrameMasks.set(animation.frameId,cropAlpha(actorSourceMask,frame));
  const actorMask=frame?actorFrameMasks.get(animation.frameId)!:null;
