    const ghost=project.assets.find(a=>a.id===chosenAsset);if(ghost&&['place','brush','paint-rect'].includes(tool)){const p=tool==='place'?snapped(hover):gridStroke(hover,hover,brushStep())[0];const b=bounds({x:p.x,y:p.y,scale:1,flipX:false} as EditorObject,ghost);ctx.save();ctx.globalAlpha=.45;ctx.imageSmoothingEnabled=false;for(const part of ghost.parts){const img=images.get(part.file);if(img)ctx.drawImage(img.image,b.left,b.top,b.w,b.h);}ctx.restore();}
