  const select=(key:string,label:string,value:string,options:string[][])=>`<label class="form-row">${label}<select data-asset-prop="${key}">${options.map(([id,name])=>`<option value="${id}" ${id===value?'selected':''}>${name}</option>`).join('')}</select></label>`;
