function validate():ReturnType<typeof auditProject> {studio.openDock('review');const issues=auditProject(project);el('issues').innerHTML=issues.length?issues.map(i=>`<button class="issue ${i.severity}" data-issue-level="${i.levelId}" ${i.entity?`data-issue-id="${i.entity.id}" data-issue-kind="${i.entity.kind}"`:''}>${esc(project.levels.find(l=>l.id===i.levelId)?.name)} · ${esc(i.message)}</button>`).join(''):'<p class="hint">Không có lỗi Spawn, vùng hoặc cửa nối. ART/bố cục vẫn cần bạn đánh giá.</p>';status(`Kiểm level: ${issues.filter(i=>i.severity==='error').length} lỗi, ${issues.filter(i=>i.severity==='warning').length} lưu ý.`);return issues;}
