el('issues').addEventListener('click',e=>{if(playing)return;const b=(e.target as HTMLElement).closest<HTMLElement>('[data-issue-level]');if(!b)return;if(!project.levels.some(l=>l.id===b.dataset.issueLevel)){el('issues').innerHTML='<p class="hint">Dữ liệu đã đổi. Bấm Kiểm tra để cập nhật.</p>';return;}activate(b.dataset.issueLevel!);if(b.dataset.issueId){editDomain=b.dataset.issueKind==='region'?'navigation':'scene';choose({kind:b.dataset.issueKind as 'object'|'region',id:b.dataset.issueId});ui();frameSelection();}else{zoomTo(1);view.x=viewport.clientWidth/2-level().spawn.x;view.y=viewport.clientHeight/2-level().spawn.y;}});
function minimapTransform(){const c=el<HTMLCanvasElement>('minimap'),l=level(),scale=Math.min(c.width/l.width,c.height/l.height);return {c,l,scale,x:(c.width-l.width*scale)/2,y:(c.height-l.height*scale)/2};}
function drawMinimap():void {const {c,l,scale,x,y}=minimapTransform(),m=c.getContext('2d')!;m.setTransform(1,0,0,1,0,0);m.clearRect(0,0,c.width,c.height);m.translate(x,y);m.scale(scale,scale);m.fillStyle=l.background;m.fillRect(0,0,l.width,l.height);for(const o of l.objects){const layer=l.layers.find(l=>l.id===o.layerId);if(!layer||(playing?!layer.enabled:!layer.visible))continue;const a=project.assets.find(a=>a.id===o.assetId)!,b=bounds(o,a);m.fillStyle=a.category==='terrain'?'#9baa72':'#54735b';m.fillRect(b.left,b.top,b.w,b.h);}for(const r of l.regions){m.beginPath();r.points.forEach((p,i)=>i?m.lineTo(p.x,p.y):m.moveTo(p.x,p.y));m.closePath();m.fillStyle=regionActivity(l,r)!=='active'?'#8994a244':r.kind==='block'?'#b65c5088':r.kind==='portal'?'#8b5ee7aa':'#6eb58744';m.fill();}m.strokeStyle='#fff';m.lineWidth=1/scale;m.strokeRect(-view.x/view.zoom,-view.y/view.zoom,viewport.clientWidth/view.zoom,viewport.clientHeight/view.zoom);m.fillStyle='#3266c4';m.beginPath();m.arc(playing?player.x:l.spawn.x,playing?player.y:l.spawn.y,3/scale,0,Math.PI*2);m.fill();}
el('minimap').addEventListener('pointerdown',e=>{if(playing)return;const {c,scale,x,y}=minimapTransform(),b=c.getBoundingClientRect(),wx=((e.clientX-b.left)*c.width/b.width-x)/scale,wy=((e.clientY-b.top)*c.height/b.height-y)/scale;view.x=viewport.clientWidth/2-wx*view.zoom;view.y=viewport.clientHeight/2-wy*view.zoom;});
