const assetCut=setupAssetCut({
  backup:source=>cloneLibraryAsset(source.id,false),
  assets:()=>project.assets,
  context:(id?:string)=>{
    const current=object(),background=[...level().objects].filter(o=>level().layers.some(l=>l.id===o.layerId&&l.kind==='ground')).sort((a,b)=>{const aa=project.assets.find(v=>v.id===a.assetId)!,bb=project.assets.find(v=>v.id===b.assetId)!;return bb.width*bb.height-aa.width*aa.height;})[0];
    const asset=project.assets.find(a=>a.id===(id??(current?.assetId||(inspectorContext==='asset'?chosenAsset:'')||background?.assetId||chosenAsset)))??[...project.assets].sort((a,b)=>b.width*b.height-a.width*a.height)[0];
    if(!asset)return;const source=current?.assetId===asset.id?current:background?.assetId===asset.id?background:level().objects.find(o=>o.assetId===asset.id);
    return {asset:structuredClone(asset),...(source?{object:structuredClone(source)}:{})};
  },
  image:file=>{const loaded=images.get(file);if(!loaded)throw new Error('Ảnh nguồn chưa nạp.');return loaded.image;},status,
  add:async(asset,source,place)=>{
    if(playing)throw new Error('Dừng Test để cắt asset.');if(project.assets.length>=200)throw new Error('Thư viện tối đa 200 asset.');
    const next=structuredClone(project),l=next.levels.find(v=>v.id===next.activeLevelId)!;next.assets.push(asset);let placed:EditorObject|undefined;
    if(place){const o=l.objects.find(o=>o.id===source.object?.id),base=l.layers.find(v=>v.kind===asset.defaultLayer),cover=l.layers.find(v=>v.kind==='cover');if(!o||o.assetId!==source.asset.id)throw new Error('Không còn instance nguồn trong level.');if(!base||!cover||base.locked||(asset.parts.some(p=>p.cover)&&cover.locked))throw new Error('Mở khóa layer đích trước khi đặt bản cắt, hoặc bỏ chọn Đặt bản cắt.');if(l.objects.length>=10000)throw new Error('Level tối đa 10000 instance.');placed={id:uid(),name:asset.name,assetId:asset.id,layerId:base.id,coverLayerId:cover.id,...cutPlacement(source.asset,o,asset.extraction!.bounds,asset.pivot),scale:o.scale,flipX:o.flipX,opacity:o.opacity,locked:false};l.objects.push(placed);}
    const validated=parseProject(next);await loadAssets(validated);setDomain('scene');
    if(!edit(()=>{project=validated;chosenAsset=asset.id;chosenPrefab='';if(placed){choose({kind:'object',id:placed.id},false,true);activeLayer=placed.layerId;}else{clearSelection();inspectorContext='asset';}}))throw new Error('Không thêm được asset vào dự án.');
    setTool('select');ui();
  }
});
